with lines as (select id, host, level, latency_ms, status_code, key, value from app_logs lateral view explode(context) t as key, value) select key, approx_percentile(latency_ms, array(0.25, 0.5, 0.75)) as latency_ms_quartiles, count(*) filter (where key = 'trace') as trace_rows, stddev_samp(status_code) as status_code_stddev, sort_array(collect_set(level)) as level_list, approx_percentile(status_code, array(0.25, 0.5, 0.75)) as status_code_quartiles, sum(case when host = 'h1' then latency_ms else 0 end) as h1_latency_ms from lines group by key;
